def regex_search(pattern: str, text: str) -> bool:
    class Parser:
        def __init__(self, pattern: str):
            self.s = pattern
            self.n = len(pattern)
            self.pos = 0
            self.eps = []
            self.char_trans = []

        def new_state(self):
            idx = len(self.eps)
            self.eps.append([])
            self.char_trans.append([])
            return idx

        def add_eps(self, frm: int, to: int, cond=None):
            self.eps[frm].append((to, cond))

        def add_lit(self, frm: int, to: int, ch: str):
            self.char_trans[frm].append((0, ch, to))

        def add_dot(self, frm: int, to: int):
            self.char_trans[frm].append((1, None, to))

        def add_class(self, frm: int, to: int, intervals, neg: bool):
            self.char_trans[frm].append((2, (intervals, neg), to))

        def make_empty(self):
            s = self.new_state()
            e = self.new_state()
            self.add_eps(s, e)
            return s, e

        def merge_intervals(self, intervals):
            if not intervals:
                return ()
            intervals = sorted(intervals)
            merged = []
            a, b = intervals[0]
            for x, y in intervals[1:]:
                if x <= b + 1:
                    if y > b:
                        b = y
                else:
                    merged.append((a, b))
                    a, b = x, y
            merged.append((a, b))
            return tuple(merged)

        def concat(self, frags):
            if not frags:
                return self.make_empty()
            s, e = frags[0]
            for ns, ne in frags[1:]:
                self.add_eps(e, ns)
                e = ne
            return s, e

        def star(self, frag):
            s, e = frag
            ns = self.new_state()
            ne = self.new_state()
            self.add_eps(ns, s)
            self.add_eps(ns, ne)
            self.add_eps(e, ne)
            self.add_eps(e, ns)
            return ns, ne

        def plus(self, frag):
            s, e = frag
            ns = self.new_state()
            ne = self.new_state()
            self.add_eps(ns, s)
            self.add_eps(e, ns)
            self.add_eps(e, ne)
            return ns, ne

        def question(self, frag):
            s, e = frag
            ns = self.new_state()
            ne = self.new_state()
            self.add_eps(ns, s)
            self.add_eps(ns, ne)
            self.add_eps(e, ne)
            return ns, ne

        def parse_alternation(self):
            frags = [self.parse_sequence()]
            while self.pos < self.n and self.s[self.pos] == "|":
                self.pos += 1
                frags.append(self.parse_sequence())
            return self.concat(frags)

        def parse_sequence(self):
            frags = []
            while self.pos < self.n:
                c = self.s[self.pos]
                if c == "|" or c == ")":
                    break
                if c in "*+?":
                    raise ValueError("invalid quantifier")

                frag, typ = self.parse_atom()

                if self.pos < self.n and self.s[self.pos] in "*+?":
                    if typ == "anchor":
                        raise ValueError("invalid quantifier after anchor")
                    q = self.s[self.pos]
                    self.pos += 1
                    if q == "*":
                        frag = self.star(frag)
                    elif q == "+":
                        frag = self.plus(frag)
                    else:
                        frag = self.question(frag)

                frags.append(frag)

            return self.concat(frags)

        def parse_atom(self):
            if self.pos >= self.n:
                raise ValueError("unexpected end of pattern")

            c = self.s[self.pos]

            if c == "(":
                self.pos += 1
                frag = self.parse_alternation()
                if self.pos >= self.n or self.s[self.pos] != ")":
                    raise ValueError("unbalanced parenthesis")
                self.pos += 1
                return frag, "group"

            if c == ".":
                self.pos += 1
                s = self.new_state()
                e = self.new_state()
                self.add_dot(s, e)
                return s, e, "atom"

            if c == "^":
                self.pos += 1
                s = self.new_state()
                e = self.new_state()
                self.add_eps(s, e, "^")
                return s, e, "anchor"

            if c == "$":
                self.pos += 1
                s = self.new_state()
                e = self.new_state()
                self.add_eps(s, e, "$")
                return s, e, "anchor"

            if c == "[":
                frag = self.parse_class()
                return frag[0], frag[1], "atom"

            if c == "\\":
                if self.pos + 1 >= self.n:
                    raise ValueError("trailing backslash")
                ch = self.s[self.pos + 1]
                self.pos += 2
                s = self.new_state()
                e = self.new_state()
                self.add_lit(s, e, ch)
                return s, e, "atom"

            if c == ")" or c == "|":
                raise ValueError("unexpected parenthesis or alternation")

            self.pos += 1
            s = self.new_state()
            e = self.new_state()
            self.add_lit(s, e, c)
            return s, e, "atom"

        def parse_class(self):
            s = self.s
            pos = self.pos

            if pos >= self.n or s[pos] != "[":
                raise ValueError("invalid class")

            pos += 1
            neg = False
            if pos < self.n and s[pos] == "^":
                neg = True
                pos += 1

            intervals = []
            closed = False

            while pos < self.n:
                if s[pos] == "]":
                    closed = True
                    break

                if s[pos] == "\\":
                    if pos + 1 >= self.n:
                        raise ValueError("invalid class")
                    x = s[pos + 1]
                    pos += 2
                else:
                    x = s[pos]
                    pos += 1

                if pos < self.n and s[pos] == "-" and pos + 1 < self.n and s[pos + 1] != "]":
                    if s[pos + 1] == "\\":
                        if pos + 2 >= self.n:
                            raise ValueError("invalid class")
                        y = s[pos + 2]
                        pos += 3
                    else:
                        y = s[pos + 1]
                        pos += 2

                    if ord(x) > ord(y):
                        raise ValueError("invalid range")
                    intervals.append((ord(x), ord(y)))
                else:
                    intervals.append((ord(x), ord(x)))

            if not closed:
                raise ValueError("unclosed class")

            self.pos = pos + 1

            if not intervals:
                raise ValueError("empty class")

            intervals = self.merge_intervals(intervals)
            st = self.new_state()
            en = self.new_state()
            self.add_class(st, en, intervals, neg)
            return st, en

    parser = Parser(pattern)
    start, accept = parser.parse_alternation()

    if parser.pos != len(pattern):
        raise ValueError("invalid pattern")

    text_len = len(text)
    eps = parser.eps
    char_trans = parser.char_trans

    def eps_closure(states, pos):
        stack = list(states)
        seen = set(states)
        while stack:
            u = stack.pop()
            for v, cond in eps[u]:
                if cond is None:
                    ok = True
                elif cond == "^":
                    ok = pos == 0
                else:
                    ok = pos == text_len

                if ok and v not in seen:
                    seen.add(v)
                    stack.append(v)
        return seen

    def move(states, ch):
        res = set()
        cp = None

        for u in states:
            for kind, data, to in char_trans[u]:
                if kind == 0:
                    if data == ch:
                        res.add(to)
                elif kind == 1:
                    res.add(to)
                else:
                    if cp is None:
                        cp = ord(ch)
                    intervals, neg = data
                    inside = False
                    for a, b in intervals:
                        if a <= cp <= b:
                            inside = True
                            break
                    if inside ^ neg:
                        res.add(to)
        return res

    active = eps_closure({start}, 0)
    if accept in active:
        return True

    for i, ch in enumerate(text):
        nxt = move(active, ch)
        nxt.add(start)
        active = eps_closure(nxt, i + 1)
        if accept in active:
            return True

    return False
